CREATE OR REPLACE FUNCTION public.create_vendor_payment_draft(p_legal_entity_id UUID,p_vendor_id UUID,p_payment_number TEXT,p_payment_date DATE,p_amount NUMERIC,p_currency_code CHAR(3),p_reference TEXT,p_allocations JSONB)
RETURNS public.vendor_payments LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v public.vendors%ROWTYPE; p public.vendor_payments%ROWTYPE; allocated NUMERIC; BEGIN
 IF NOT public.current_user_can_manage_legal_entity(p_legal_entity_id) THEN RAISE EXCEPTION 'Not authorised'; END IF; SELECT * INTO v FROM public.vendors WHERE id=p_vendor_id AND legal_entity_id=p_legal_entity_id AND is_active; IF NOT FOUND THEN RAISE EXCEPTION 'Invalid vendor'; END IF;
 SELECT COALESCE(SUM((x->>'allocated_amount')::NUMERIC),0) INTO allocated FROM jsonb_array_elements(p_allocations) x; IF p_amount<=0 OR allocated<>p_amount THEN RAISE EXCEPTION 'Payment amount must equal allocations'; END IF;
 INSERT INTO public.vendor_payments(tenant_id,legal_entity_id,vendor_id,payment_number,payment_date,amount,currency_code,reference,status,created_by) VALUES(v.tenant_id,p_legal_entity_id,p_vendor_id,btrim(p_payment_number),p_payment_date,p_amount,p_currency_code,NULLIF(btrim(p_reference),''),'draft',auth.uid()) RETURNING * INTO p;
 INSERT INTO public.vendor_payment_allocations(tenant_id,legal_entity_id,payment_id,ap_invoice_id,allocated_amount) SELECT v.tenant_id,p_legal_entity_id,p.id,(x->>'ap_invoice_id')::UUID,(x->>'allocated_amount')::NUMERIC FROM jsonb_array_elements(p_allocations) x;
 RETURN p; END; $$;
REVOKE ALL ON FUNCTION public.create_vendor_payment_draft(UUID,UUID,TEXT,DATE,NUMERIC,CHAR(3),TEXT,JSONB) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_vendor_payment_draft(UUID,UUID,TEXT,DATE,NUMERIC,CHAR(3),TEXT,JSONB) TO authenticated;
